"""Exact-node unstructured P1 meshes, generated by Gmsh (not SciPy)."""
import sys, math
sys.path.insert(0, '/workspace/setup-python')
import gmsh
import numpy as np
from pathlib import Path

def generate(n):
    gmsh.initialize()
    gmsh.option.setNumber('General.Terminal',0)
    gmsh.model.add(f'square_{n}')
    m=max(3,round(math.sqrt(n))-1)
    boundary=[]
    for side in range(4):
        for j in range(m):
            t=j/m
            boundary.append([(t,0),(1,t),(1-t,1),(0,1-t)][side])
    ni=n-len(boundary)
    q=math.ceil(math.sqrt(ni))
    rng=np.random.default_rng(20261011+n)
    # Stratified, jittered interior points. Keep all points distinct from the boundary.
    pts=[((i+.5+rng.uniform(-.22,.22))/q,(j+.5+rng.uniform(-.22,.22))/q)
         for j in range(q) for i in range(q)]
    # Distribute omitted grid points over the domain, rather than deleting a strip.
    keep=np.sort(rng.choice(len(pts),ni,replace=False))
    interior=[pts[i] for i in keep]
    ids=[gmsh.model.geo.addPoint(x,y,0,2) for x,y in boundary+interior]
    lines=[gmsh.model.geo.addLine(ids[i],ids[(i+1)%len(boundary)]) for i in range(len(boundary))]
    loop=gmsh.model.geo.addCurveLoop(lines)
    surface=gmsh.model.geo.addPlaneSurface([loop])
    gmsh.model.geo.synchronize()
    gmsh.model.mesh.embed(0,ids[len(boundary):],2,surface)
    gmsh.option.setNumber('Mesh.Algorithm',5)
    gmsh.option.setNumber('Mesh.MeshSizeMin',2)
    gmsh.option.setNumber('Mesh.MeshSizeMax',2)
    gmsh.option.setNumber('Mesh.MeshSizeFromPoints',0)
    gmsh.option.setNumber('Mesh.MeshSizeFromCurvature',0)
    gmsh.option.setNumber('Mesh.MeshSizeExtendFromBoundary',0)
    gmsh.option.setNumber('Mesh.MshFileVersion',2.2)
    gmsh.model.mesh.generate(2)
    tags,coords,_=gmsh.model.mesh.getNodes()
    assert len(tags)==n,(n,len(tags))
    gmsh.write(f'mesh_{n}.msh')
    xyz=np.array(coords).reshape(-1,3)
    mapping={int(tag):i for i,tag in enumerate(tags)}
    etypes,_,enodes=gmsh.model.mesh.getElements(2)
    tri=[]
    for typ,nodes in zip(etypes,enodes):
        assert typ==2
        tri.extend([[mapping[int(t)] for t in row] for row in np.array(nodes).reshape(-1,3)])
    # Compact companion data for the standalone C solver; the .msh is its primary input.
    print(n,len(tri),len(boundary))
    gmsh.finalize()

if __name__=='__main__':
    for n in (100,1000,10000): generate(n)
